flow.typescript:
// D3 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d03_flow.ts
//   사인파의 합 → FFT → 해상도 · 창 → STFT → Mel → MFCC 를 합성 음성 하나로 끝까지
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const WIN = 400; // 25 ms
const HOP = 160; // 10 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움 (Python은 400 그대로)

function stftPower(y: Float32Array, win: number = WIN, hop: number = HOP, nfft: number = NFFT): Float64Array[] {
  // 프레임마다 [자르고 -> 주기형 Hann 곱하고 -> FFT] 한 파워 스펙트럼 |X|^2, 프레임 수 = 1 + floor((L - win) / hop)
  const w = Float64Array.from({ length: win }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / win));
  const out: Float64Array[] = [];
  for (let s = 0; s + win <= y.length; s += hop) {
    const m = magnitude(y.subarray(s, s + win), nfft, w);
    out.push(m.map((v) => v * v));
  }
  return out;
}

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금): 낮은 소리는 촘촘하게, 높은 소리는 성기게. 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMel(power: Float64Array[], bank: Float64Array[]): number[][] {
  // [프레임][mel] dB, 가장 센 값 = 0 dB (power_to_db(ref=max) 와 같은 생각)
  const mel = power.map((p) => bank.map((row) => row.reduce((a, w, k) => a + w * p[k], 0)));
  const top = mel.reduce((a, f) => Math.max(a, ...f), 1e-10);
  return mel.map((f) => f.map((v) => 10 * Math.log10(Math.max(v, 1e-10) / top)));
}

function dct(x: ArrayLike<number>): Float64Array {
  // DCT-II (norm="ortho"): X[k] = s_k sum x[n] cos(pi (2n + 1) k / 2N)
  const N = x.length;
  return Float64Array.from({ length: N }, (_, k) => {
    let s = 0;
    for (let n = 0; n < N; n++) s += x[n] * Math.cos((Math.PI * (2 * n + 1) * k) / (2 * N));
    return s * Math.sqrt((k === 0 ? 1 : 2) / N);
  });
}

function idct(X: ArrayLike<number>): Float64Array {
  // 역변환 (DCT-III, norm="ortho")
  const N = X.length;
  return Float64Array.from({ length: N }, (_, n) => {
    let s = 0;
    for (let k = 0; k < N; k++) s += X[k] * Math.sqrt((k === 0 ? 1 : 2) / N) * Math.cos((Math.PI * (2 * n + 1) * k) / (2 * N));
    return s;
  });
}


// 1) 소리는 사인파의 합: 도 · 미 · 솔 화음을 FFT로 쪼개면 세 높이가 나온다
const [c1, c2, c3] = [tone(262), tone(330), tone(392)];
const chord = c1.map((v, i) => v + c2[i] + c3[i]);
const m = magnitude(chord, 16384, undefined); // 1초 = 16000개 → 16384칸(0으로 채움)
const bins = Array.from(m, (v, k) => [v, k]).sort((a, b) => b[0] - a[0]);
const top3: number[] = [];
for (const [, k] of bins) if (top3.every((t) => Math.abs(t - k) > 20)) top3.push(k); // 이웃 칸은 같은 봉우리
const peaks = top3.slice(0, 3).map((k) => Math.round((k * SR) / 16384)).sort((a, b) => a - b);
console.log("가장 큰 세 주파수:", peaks.join(", "));
check(peaks.every((p, i) => Math.abs(p - [262, 330, 392][i]) <= 2), "도 262 · 미 330 · 솔 392 Hz 가 나와야 해요.");

// 2) DFT는 곱해서 더하기: 정의대로 계산(N^2번) = FFT
const x = tone(440, 1024 / SR);
const N = x.length;
let worst = 0;
const fm = magnitude(x, N);
for (let k = 0; k <= N / 2; k += 7) {
  let re = 0;
  let im = 0;
  for (let n = 0; n < N; n++) {
    re += x[n] * Math.cos((2 * Math.PI * k * n) / N);
    im -= x[n] * Math.sin((2 * Math.PI * k * n) / N);
  }
  worst = Math.max(worst, Math.abs(Math.hypot(re, im) - fm[k]));
}
console.log(`DFT 정의 vs FFT 최대 차이 ${worst.toExponential(2)}`);
check(worst < 1e-3, "DFT 정의대로 계산한 결과가 FFT와 같아야 해요.");

// 3) 창 함수: 칸에 안 맞는 445 Hz는 새어 나가고, Hann 창이 새는 것을 줄인다
const x445 = tone(445, 512 / SR);
const leak = (win?: Float64Array): number => {
  const mm = magnitude(x445, 512, win);
  const top = Math.max(...mm);
  return 20 * Math.log10(mm[Math.round((1500 * 512) / SR)] / top + 1e-12);
};
console.log(`1,500 Hz 근처 새어 나간 세기: rect ${leak().toFixed(1)} dB · hann ${leak(hann(512)).toFixed(1)} dB`);
check(leak(hann(512)) < leak() - 20, "Hann 창이 훨씬 덜 새어야 해요.");

// 4) STFT: 25 ms 창, 10 ms hop → 프레임 수 = 1 + floor((L - 400) / 160)
const y = synthVoice(2);
const P = stftPower(y);
console.log(`STFT 모양: ${P.length}프레임 x ${P[0].length}칸 (예측 ${1 + Math.floor((y.length - WIN) / HOP)})`);
check(P.length === 1 + Math.floor((y.length - WIN) / HOP) && P[0].length === NFFT / 2 + 1, "프레임 수 = 1 + (L - 400) // 160 입니다.");

// 5) Mel: 필터뱅크 행렬 곱,  6) MFCC: Log-Mel의 DCT 앞 13개
const bank = melBank(SR, NFFT, 80);
const lm = logMel(P, bank);
console.log(`필터뱅크 (${bank.length}, ${bank[0].length}) · Log-Mel (${lm.length} 프레임, ${lm[0].length}채널)`);
check(bank.length === 80 && lm[0].length === 80 && lm.flat().every((v) => v <= 1e-9), "필터뱅크는 80개, 가장 센 값이 0 dB 입니다.");
const mfcc = lm.map((f) => dct(f).slice(0, 13));
console.log(`MFCC: ${mfcc.length} 프레임 x ${mfcc[0].length}개`);
const back = idct(dct(lm[50])); // DCT -> 역DCT는 원래대로
check(mfcc[0].length === 13 && back.every((v, i) => Math.abs(v - lm[50][i]) < 1e-6), "MFCC는 13개, DCT는 되돌릴 수 있어요.");

sum.typescript:
// D3 · Part 1 · 소리는 사인파의 합이다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d03_sum.ts
//   세 사인파를 더한 소리를 FFT로 쪼개 크기를 되찾고, 포먼트 모음 '아'·'이'의 봉우리 위치를 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


function vowel(f0: number, F1: number, F2: number, sec: number = 1, sr: number = SR): Float32Array {
  // 간단한 포먼트 합성: 배음 f0, 2f0, 3f0, ...을 더하되 F1, F2 근처 배음을 크게
  const y = new Float32Array(Math.floor(sr * sec));
  for (let k = 1; k < Math.floor(sr / 2 / f0); k++) {
    const f = k * f0;
    const g = Math.exp(-(((f - F1) / 150) ** 2)) + 0.7 * Math.exp(-(((f - F2) / 200) ** 2)) + 0.02;
    for (let i = 0; i < y.length; i++) y[i] += g * Math.sin((2 * Math.PI * f * i) / sr);
  }
  const peak = y.reduce((a, v) => Math.max(a, Math.abs(v)), 1e-9);
  return y.map((v) => (0.8 * v) / peak);
}

const VOWELS: Record<string, [number, number]> = { 아: [700, 1200], 이: [300, 2300], 우: [300, 800] }; // 모음 -> [F1, F2] Hz


const parts: Array<[string, number, number]> = [["220 Hz x 0.5", 220, 0.5], ["440 Hz x 0.3", 440, 0.3], ["660 Hz x 0.2", 660, 0.2]];
const mix = new Float32Array(SR);
for (const [, f, a] of parts) tone(f, 1, SR, a).forEach((v, i) => (mix[i] += v)); // 세 개를 더한 소리

// 합쳐진 소리를 FFT로 쪼개면 A = 2|X[k]| / N 으로 각 사인파의 크기를 되찾는다 (1초 = 16000개 = 칸 간격 1 Hz, 16000은 FFT 길이가 아니라서 DFT로)
function amp(x: Float32Array, f: number): number {
  let re = 0;
  let im = 0;
  for (let n = 0; n < x.length; n++) {
    re += x[n] * Math.cos((2 * Math.PI * f * n) / SR);
    im -= x[n] * Math.sin((2 * Math.PI * f * n) / SR);
  }
  return (2 * Math.hypot(re, im)) / x.length;
}
for (const [name, f, a] of parts) console.log(`${name}: 되찾은 진폭 ${amp(mix, f).toFixed(3)} (실제 ${a})`);
check(parts.every(([, f, a]) => Math.abs(amp(mix, f) - a) < 0.01), "합친 소리에서 각 사인파의 크기를 되찾아야 해요.");

// 빈칸 실습 1의 답: 도-미-솔 화음 (FFT 길이 16384)
const [c1, c2, c3] = [tone(262), tone(330), tone(392)];
const chord = c1.map((v, i) => v + c2[i] + c3[i]);
const m = magnitude(chord, 16384);
const order = Array.from(m, (v, k) => [v, k]).sort((a, b) => b[0] - a[0]);
const picked: number[] = [];
for (const [, k] of order) if (picked.every((p) => Math.abs(p - k) > 20)) picked.push(k);
const peaks = picked.slice(0, 3).map((k) => Math.round((k * SR) / 16384)).sort((a, b) => a - b);
console.log("가장 큰 세 주파수:", peaks.join(", "));
check(peaks.every((p, i) => Math.abs(p - [262, 330, 392][i]) <= 2), "솔은 392 Hz입니다.");

// 포먼트: 같은 높이(150 Hz)라도 F1, F2 근처 배음이 커서 모음이 달라진다
const lowPeak = (y: Float32Array): number => {
  const mm = magnitude(y, 16384);
  let best = 0;
  for (let k = Math.round((200 * 16384) / SR); k < Math.round((1000 * 16384) / SR); k++) if (mm[k] > mm[best]) best = k;
  return (best * SR) / 16384;
};
for (const [v, [F1, F2]] of Object.entries(VOWELS)) console.log(`"${v}" F1=${F1} Hz, F2=${F2} Hz → 1000 Hz 아래 가장 센 소리 ${lowPeak(vowel(150, F1, F2)).toFixed(0)} Hz`);
check(Math.abs(lowPeak(vowel(150, ...VOWELS["아"])) - 700) <= 75 && Math.abs(lowPeak(vowel(150, ...VOWELS["이"])) - 300) <= 75, "'아'는 700 Hz, '이'는 300 Hz 근처가 가장 세요.");

dft.typescript:
// D3 · Part 2 · DFT: 어떤 높이가 얼마나 들어 있는지 재는 방법 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d03_dft.ts
//   cos · sin을 곱해서 더하기로 주파수 성분 재기 → DFT 정의 = FFT, 진폭 되돌리기와 bin 번호 ↔ Hz
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 25 ms(400개) 안에 440 Hz(0.5)와 1000 Hz(0.25)를 섞고, 시험 주파수마다 cos · sin을 곱해서 더한다
const N0 = 400;
const x0 = Float32Array.from({ length: N0 }, (_, n) => 0.5 * Math.sin((2 * Math.PI * 440 * n) / SR) + 0.25 * Math.sin((2 * Math.PI * 1000 * n) / SR));
const mags: Record<number, number> = {};
console.log("시험 주파수  cos 곱의 합  sin 곱의 합     크기");
for (const fp of [300, 440, 700, 1000, 1500]) {
  let c = 0;
  let s = 0;
  for (let n = 0; n < N0; n++) {
    c += x0[n] * Math.cos((2 * Math.PI * fp * n) / SR);
    s += x0[n] * Math.sin((2 * Math.PI * fp * n) / SR);
  }
  mags[fp] = (Math.hypot(c, s) * 2) / N0;
  console.log(`${String(fp).padStart(8)} Hz ${c.toFixed(2).padStart(11)} ${s.toFixed(2).padStart(11)} ${mags[fp].toFixed(3).padStart(8)}`);
}
check(Math.abs(mags[440] - 0.5) < 0.03 && Math.abs(mags[1000] - 0.25) < 0.03 && mags[700] < 0.05, "들어 있는 440 · 1000 Hz에서만 크기가 크게 나와야 해요.");

function dft(x: ArrayLike<number>): { re: Float64Array; im: Float64Array } {
  // DFT 정의 그대로: X[k] = sum x[n] e^{-j 2 pi k n / N}  (N x N번 곱하기)
  const N = x.length;
  const re = new Float64Array(N);
  const im = new Float64Array(N);
  for (let k = 0; k < N; k++) {
    for (let n = 0; n < N; n++) {
      re[k] += x[n] * Math.cos((2 * Math.PI * k * n) / N);
      im[k] -= x[n] * Math.sin((2 * Math.PI * k * n) / N);
    }
  }
  return { re, im };
}

const x = tone(440, 1024 / SR); // 1024 샘플 (64 ms)
const N = x.length;
let t0 = performance.now();
const d = dft(x);
const tDft = performance.now() - t0;
const re = Float64Array.from(x);
const im = new Float64Array(N);
t0 = performance.now();
fft(re, im);
const tFft = performance.now() - t0;
const diff = Math.max(...d.re.map((v, k) => Math.max(Math.abs(v - re[k]), Math.abs(d.im[k] - im[k]))));
console.log(`직접 DFT ${tDft.toFixed(1)} ms | FFT ${tFft.toFixed(3)} ms | 최대 차이 ${diff.toExponential(2)}`);
check(diff < 1e-6 && tFft < tDft, "결과는 같고 FFT가 더 빨라야 해요.");

// 빈칸 실습 2의 답: f_k = k x fs / N, 크기는 hypot (복소수의 절댓값)
const mag = d.re.map((v, k) => Math.hypot(v, d.im[k]));
let kPeak = 0;
for (let k = 0; k < N / 2; k++) if (mag[k] > mag[kPeak]) kPeak = k;
console.log(`가장 큰 bin k = ${kPeak} -> ${((kPeak * SR) / N).toFixed(1)} Hz (bin 간격 ${(SR / N).toFixed(3)} Hz)`);
check(Math.abs((kPeak * SR) / N - 440) < SR / N, "f_k = k x fs / N 입니다.");

// 수식 검증: 칸에 정확히 맞는 주파수는 A = 2|X[k]| / N 으로 진폭이 그대로 돌아온다
let ok = true;
for (const [f, A] of [[500, 0.5], [1000, 0.25], [437.5, 0.8]]) {
  const xx = tone(f, N / SR, SR, A);
  const r = Float64Array.from(xx);
  const i = new Float64Array(N);
  fft(r, i);
  const k = Math.round(f / (SR / N));
  const got = (2 * Math.hypot(r[k], i[k])) / N;
  ok = ok && Math.abs(got - A) < 1e-3;
  console.log(`${f.toFixed(1).padStart(7)} Hz (k=${String(k).padStart(3)}): 2|X[k]|/N = ${got.toFixed(4)} | 실제 진폭 ${A}`);
}
console.log(`곱셈 횟수 DFT N^2 = ${(N * N).toLocaleString()} vs FFT N log2 N = ${(N * Math.log2(N)).toLocaleString()}`);
check(ok, "2|X[k]|/N 이 실제 진폭과 같아야 해요.");

