// D3 · Part 4 · STFT와 스펙트로그램 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d03_stft.ts
//   자르기 → 창 곱하기 → FFT 를 직접 만들어 frame 수 공식(25 ms 창 · 10 ms hop)과 1 kHz 봉우리 위치를 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
