// D3 · Part 4 · 시간-주파수 트레이드오프 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d03_live.ts
//   창 길이 2048 · 400 · 128 로 같은 소리를 보면 주파수는 또렷할수록 시간이 흐려진다(Δf x 창 길이 = 1)
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const [a440, a460] = [tone(440, 1), tone(460, 1)];
const two = a440.map((v, i) => v + a460[i]); // 20 Hz 차이 두 소리
const burst = new Float32Array(SR);
burst.set(tone(1000, 320 / SR), 8000); // 0.5초에 20 ms 짧은 소리

function frames(y: Float32Array, n: number, hop: number = 64): Float64Array[] {
  // 창 길이 n(2의 거듭제곱)으로 hop 간격 STFT 크기
  const w = hann(n);
  const out: Float64Array[] = [];
  for (let s = 0; s + n <= y.length; s += hop) out.push(magnitude(y.subarray(s, s + n), n, w));
  return out;
}

function splitTwo(n: number): boolean {
  // 440 Hz와 460 Hz가 두 봉우리로 갈라지는가 (440 ~ 460 Hz 사이 골이 깊은가)
  const S = frames(two, n)[Math.floor((SR / 2 - n) / 64)];
  const idx = (f: number): number => Math.round((f * n) / SR);
  const [a, b, mid] = [idx(440), idx(460), idx(450)];
  return a !== b && S[mid] < 0.7 * Math.min(S[a], S[b]);
}

function timeSpread(n: number): number {
  // 짧은 소리가 시간 축에서 퍼진 길이(초): 가장 센 값보다 20 dB 이내인 프레임 수 x hop
  const e = frames(burst, n).map((m) => m.reduce((a, v) => a + v * v, 0));
  const top = Math.max(...e);
  return (e.filter((v) => 10 * Math.log10(v / top + 1e-12) > -20).length * 64) / SR;
}

const rows = [2048, 512, 128].map((n) => ({ n, df: SR / n, dt: n / SR, split: splitTwo(n), spread: timeSpread(n) }));
for (const r of rows) console.log(`n=${String(r.n).padStart(4)}: 주파수 칸 ${r.df.toFixed(1).padStart(6)} Hz · 창 ${(r.dt * 1000).toFixed(1).padStart(6)} ms · 440/460 Hz 구분 ${String(r.split).padEnd(5)} · 짧은 소리가 퍼진 시간 ${(r.spread * 1000).toFixed(0).padStart(4)} ms`);
console.log("Δf x 창 길이 =", rows.map((r) => (r.df * r.dt).toFixed(3)).join(", "), "(늘 1)");
check(rows.every((r) => Math.abs(r.df * r.dt - 1) < 1e-9), "Δf x 창 길이 = fs/N x N/fs = 1 입니다.");
check(rows[0].split && !rows[2].split && rows[0].spread > rows[2].spread, "창이 길면 주파수는 또렷하고 시간은 흐려져요(짧으면 반대).");

